const names = ['Probe Index','Probe Agents','Probe Tasks','Probe Sessions','Probe Roster','Probe Bridge','Probe Memory','Probe Vec','Probe Content','Probe REST','Probe n8n'];
const critical = new Set(['Probe Index','Probe Agents','Probe Tasks','Probe Sessions','Probe Roster']);
const probes = {};
for (const n of names) {
  let j;
  try { j = $(n).first().json; } catch (e) { j = { error: 'no data' }; }
  let ok = false, detail = null;
  if (j && j.result) {
    const txt = j.result.content && j.result.content[0] && j.result.content[0].text;
    let parsed; try { parsed = JSON.parse(txt); } catch { parsed = txt; }
    ok = !j.result.isError;
    detail = (typeof parsed === 'object') ? parsed : String(parsed || '').slice(0, 200);
  } else if (j && (j.error || j.errorMessage || j.name === 'NodeApiError')) {
    ok = false;
    detail = String((j.error && j.error.message) || j.errorMessage || j.message || j.error || 'err').slice(0, 200);
  } else if (j && Object.keys(j).length) {
    ok = true;
    detail = j;
  } else {
    detail = 'empty';
  }
  probes[n] = { critical: critical.has(n), ok, detail };
}
const failedCritical = Object.entries(probes).filter(([, p]) => p.critical && !p.ok).map(([k]) => k);
const failedWarn = Object.entries(probes).filter(([, p]) => !p.critical && !p.ok).map(([k]) => k);
const verdict = failedCritical.length ? 'down' : (failedWarn.length ? 'degraded' : 'ok');
return [{ json: { ts: new Date().toISOString(), source: 'n8n-hphe-healthcheck', verdict, failedCritical, failedWarn, probes } }];

const report = $('Aggregate').first().json;
let prev = null, lastAlertAt = 0;
try {
  const t = $('Read Prev').first().json;
  const txt = t.result && t.result.content && t.result.content[0] && t.result.content[0].text;
  if (txt) {
    const m = JSON.parse(txt);
    if (m.memory && m.memory.content) {
      const c = JSON.parse(m.memory.content);
      prev = c.verdict || null;
      lastAlertAt = c.lastAlertAt || 0;
    }
  }
} catch (e) {}
report.previousVerdict = prev;
const fc = report.failedCritical || [], fw = report.failedWarn || [];
report.alertCtx = report.verdict + ' | critical: ' + (fc.join(', ') || '-') + ' | warn: ' + (fw.join(', ') || '-');
report.failSig = fc.slice().sort().concat(fw.slice().sort()).join(',');
const COOLDOWN_MS = 30 * 60 * 1000;
const cooled = (Date.now() - lastAlertAt) > COOLDOWN_MS;
// Cooldown pur : alerte si passage ok->incident (prev ok/null) OU rappel >30min
// pendant un incident persistant. Le flap down<->degraded ne re-alerte PAS.
report.newAlert = report.verdict !== 'ok' && (prev === 'ok' || prev === null || cooled);
report.lastAlertAt = report.newAlert ? Date.now() : lastAlertAt;
return [{ json: report }];

const report = $('Verdict').first().json;
const manual = (()=>{try{$('Webhook Manuel').first();return true}catch(e){return false}})();
const groups = {
  'Sonde-MCP-Core': ['Probe Index'],
  'Sonde-Orchestrateur': ['Probe Agents','Probe Tasks'],
  'Sonde-Roster-Chats': ['Probe Sessions','Probe Roster'],
  'Sonde-Bus-Flux': ['Probe Bridge'],
  'Sonde-Memoire-Recherche': ['Probe Memory','Probe Vec','Probe Content'],
  'Sonde-n8n-Gateways': ['Probe REST','Probe n8n']
};
const ws = 'C:/data-sys/hephaistos2-kit';
const cards = {
  'Sonde-MCP-Core': ['omniroute','chat-mvmw59wa'],
  'Sonde-Orchestrateur': ['nim','chat-mvmtldvy'],
  'Sonde-Roster-Chats': ['nim2','chat-mvpfinfra'],
  'Sonde-Bus-Flux': ['nim2','chat-mvfj8b4m'],
  'Sonde-Memoire-Recherche': ['omniroute','chat-mvmw5chd'],
  'Sonde-n8n-Gateways': ['openrouter','chat-2dca1141-dfd6-4ae2-863f-72fea217eee3'],
  'Sentinelle-Verdict': ['omniroute','chat-mvfqytbz']
};
const items = [];
const short = d => String(typeof d==='object'?JSON.stringify(d):d).slice(0,240);
// Fanout cartes : toujours si run manuel, seulement si incident en schedule
if (manual || report.verdict !== 'ok') {
  for (const [role, names] of Object.entries(groups)) {
    const lines = names.map(n => { const p=(report.probes||{})[n]||{}; return n+' : '+(p.ok?'OK':'FAIL')+' — '+short(p.detail); });
    items.push({ json: { workspaceRoot: ws, sessionId: cards[role][1], providerId: cards[role][0], timeoutSec: 60, text: '[SONDE n8n '+report.ts+']\n'+lines.join('\n') } });
  }
  const fails = [...(report.failedCritical||[]),...(report.failedWarn||[])];
  items.push({ json: { workspaceRoot: ws, sessionId: cards['Sentinelle-Verdict'][1], providerId: cards['Sentinelle-Verdict'][0], timeoutSec: 60, text: '[VERDICT n8n '+report.ts+'] '+report.verdict.toUpperCase()+(fails.length?' | echecs: '+fails.join(', '):'')+' | transition prev: '+(report.previousVerdict||'aucun') } });
}
// Reponse finale toujours vers Devin
items.push({ json: { workspaceRoot: ws, sessionId: 'acp/devin-cli/gamy-freighter', providerId: 'devin-cli', timeoutSec: 90, text: 'HEALTHCHECK n8n — verdict: '+report.verdict.toUpperCase()+' | '+((report.failedCritical||[]).concat(report.failedWarn||[])).join(', ')+' | detail: '+short(report.alertCtx||report.verdict) } });
return items;

