const res=$input.first().json;let tasks=[];
try{tasks=JSON.parse(res.result.content[0].text)}catch(e){tasks=Array.isArray(res)?res:[]}
const backlog=tasks.filter(t=>/^DIAG /.test(t.title||'')).length;
if(backlog>0)return[];
return[{json:{proceed:true}}];

